import re

def render_html_template(template_str, context):
    def eval_condition(cond_str):
        cond = cond_str.strip()
        if cond.startswith('not '):
            return not eval_condition(cond[4:])
        if ' | eq: ' in cond:
            var_name, val = cond.split(' | eq: ', 1)
            var_name = var_name.strip()
            val = val.strip().strip('"').strip("'")
            return str(context.get(var_name, '')) == val
        val = context.get(cond, None)
        return bool(val)

    # Process {% if ... %} ... {% else %} ... {% endif %}
    pattern = re.compile(r'\{%\s*if\s+(.*?)\s*%\}(.*?)(?:\{%\s*else\s*%\}(.*?))?\{%\s*endif\s*%\}', re.DOTALL)

    def replace_if(match):
        cond = match.group(1)
        if_body = match.group(2)
        else_body = match.group(3) or ""
        if eval_condition(cond):
            return render_html_template(if_body, context)
        else:
            return render_html_template(else_body, context)

    prev = ""
    res = template_str
    while prev != res:
        prev = res
        res = pattern.sub(replace_if, prev)

    # Replace {{var}}
    var_pattern = re.compile(r'\{\{\s*([a-zA-Z0-9_\.]+)\s*\}\}')
    def replace_var(match):
        var_name = match.group(1)
        val = context.get(var_name, "")
        return str(val) if val is not None else ""

    res = var_pattern.sub(replace_var, res)
    return res

def render_tex_template(template_str, context):
    def eval_condition(cond_str):
        cond = cond_str.strip()
        if cond.startswith('not '):
            return not eval_condition(cond[4:])
        if ' == ' in cond:
            var_name, val = cond.split(' == ', 1)
            return str(context.get(var_name.strip(), '')) == val.strip().strip('"').strip("'")
        val = context.get(cond, None)
        return bool(val)

    pattern = re.compile(r'<#\s*if\s+(.*?)\s*#>(.*?)(?:<#\s*else\s*#>(.*?))?<#\s*endif\s*#>', re.DOTALL)

    def replace_if(match):
        cond = match.group(1)
        if_body = match.group(2)
        else_body = match.group(3) or ""
        if eval_condition(cond):
            return render_tex_template(if_body, context)
        else:
            return render_tex_template(else_body, context)

    prev = ""
    res = template_str
    while prev != res:
        prev = res
        res = pattern.sub(replace_if, prev)

    var_pattern = re.compile(r'<<\s*([a-zA-Z0-9_\.]+)\s*>>')
    def replace_var(match):
        var_name = match.group(1)
        val = context.get(var_name, "")
