import re

def render_html_template(template_str, context):
    def eval_condition(cond_str):
        cond = cond_str.strip()
        if cond.startswith('not '):
            return not eval_condition(cond[4:])
        if ' | eq: ' in cond:
            var_name, val = cond.split(' | eq: ', 1)
            var_name = var_name.strip()
            val = val.strip().strip('"').strip("'")
            return str(context.get(var_name, '')) == val
        val = context.get(cond, None)
        return bool(val)

    # Tokenize HTML template
    # Tokens: ('IF', cond), ('ELSE', None), ('ENDIF', None), ('TEXT', text)
    token_pattern = re.compile(r'\{%\s*(if|else|endif)\s*(.*?)\s*%\}', re.DOTALL)

    tokens = []
    last_end = 0
    for m in token_pattern.finditer(template_str):
        start, end = m.span()
        if start > last_end:
            tokens.append(('TEXT', template_str[last_end:start]))
        kw = m.group(1)
        cond = m.group(2)
        if kw == 'if':
            tokens.append(('IF', cond))
        elif kw == 'else':
            tokens.append(('ELSE', None))
        elif kw == 'endif':
            tokens.append(('ENDIF', None))
